import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api, { PaginatedResponse } from 'lib/api'
import { teamLogic } from 'scenes/teamLogic'

const TAGS_PER_PAGE = 50

export interface SavedInsightsTagFilterLogicProps {
    logicKey: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface savedInsightsTagFilterLogicValues {
    currentTeamId: number | null // teamLogic
    hasMoreTagResults: boolean
    tagPage: PaginatedResponse<string> | null
    tagPageError: string | null
    tagPageLoading: boolean
    tagResults: string[]
    tagSearch: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface savedInsightsTagFilterLogicActions {
    loadMoreTagResults: () => {
        value: true
    }
    loadTagResults: ({ search, offset }: { offset: number; search: string }) => {
        search: string
        offset: number
    }
    loadTagResultsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadTagResultsSuccess: (
        tagPage: PaginatedResponse<string>,
        payload?: {
            search: string
            offset: number
        }
    ) => {
        tagPage: PaginatedResponse<string>
        payload?: {
            search: string
            offset: number
        }
    }
    setTagPopoverOpen: (open: boolean) => {
        open: boolean
    }
    setTagSearch: (search: string) => {
        search: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface savedInsightsTagFilterLogicMeta {
    key: string
}

export type savedInsightsTagFilterLogicType = MakeLogicType<
    savedInsightsTagFilterLogicValues,
    savedInsightsTagFilterLogicActions,
    SavedInsightsTagFilterLogicProps,
    savedInsightsTagFilterLogicMeta
>

export const savedInsightsTagFilterLogic = kea<savedInsightsTagFilterLogicType>([
    props({} as SavedInsightsTagFilterLogicProps),
    key((props) => props.logicKey),
    path((logicKey) => ['scenes', 'saved-insights', 'savedInsightsTagFilterLogic', logicKey]),
    connect(() => ({ values: [teamLogic, ['currentTeamId']] })),
    actions({
        loadMoreTagResults: true,
        setTagSearch: (search: string) => ({ search }),
        setTagPopoverOpen: (open: boolean) => ({ open }),
    }),
    loaders(({ values }) => ({
        tagPage: [
            null as PaginatedResponse<string> | null,
            {
                loadTagResults: async ({ search, offset }: { search: string; offset: number }, breakpoint) => {
                    if (offset === 0) {
                        await breakpoint(250)
                    }
                    if (values.currentTeamId == null) {
                        return { results: [], next: null }
                    }
                    const params = new URLSearchParams({ search, limit: String(TAGS_PER_PAGE), offset: String(offset) })
                    const tagPage: PaginatedResponse<string> = await api.get(
                        `api/projects/${values.currentTeamId}/tags?${params.toString()}`
                    )
                    breakpoint()
                    return tagPage
                },
            },
        ],
    })),
    reducers({
        tagSearch: [
            '',
            {
                setTagSearch: (_, { search }) => search,
                setTagPopoverOpen: (state, { open }) => (open ? state : ''),
            },
        ],
        tagResults: [
            [] as string[],
            {
                setTagSearch: () => [],
                setTagPopoverOpen: (state, { open }) => (open ? [] : state),
                loadTagResultsSuccess: (state, { tagPage, payload }) =>
                    payload?.offset === 0 ? (tagPage.results ?? []) : [...state, ...(tagPage.results ?? [])],
            },
        ],
        hasMoreTagResults: [
            false,
            {
                setTagSearch: () => false,
                setTagPopoverOpen: (_, { open }) => open,
                loadTagResultsSuccess: (_, { tagPage }) => tagPage.next != null,
            },
        ],
        tagPageError: [
            null as string | null,
            {
                setTagSearch: () => null,
                setTagPopoverOpen: () => null,
                loadTagResultsSuccess: () => null,
                retryTagResults: () => null,
                loadTagResultsFailure: (_, { error }) => error,
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        setTagPopoverOpen: ({ open }) => {
            if (open) {
                actions.loadTagResults({ search: '', offset: 0 })
            }
        },
        setTagSearch: ({ search }) => {
            actions.loadTagResults({ search, offset: 0 })
        },
        loadMoreTagResults: () => {
            if (values.hasMoreTagResults && !values.tagPageLoading) {
                actions.loadTagResults({ search: values.tagSearch, offset: values.tagResults.length })
            }
        },
        retryTagResults: () => {
            actions.loadTagResults({ search: values.tagSearch, offset: values.tagResults.length })
        },
    })),
])
